# owner: platform
"""Plain-text absence notices for parents."""

from rosterkit.models import Student


def _check_owner(student: Student, marks: list):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError("mark for another student")


def _absent_only(marks: list):
    for mark in marks:
        if mark.status == "absent":
            yield mark.day


def _absent_days(student: Student, marks: list):
    _check_owner(student, marks)
    days = sorted(_absent_only(marks))
    if not days:
        raise ValueError("no absences to report")
    return days


def absence_notice(student: Student, marks: list) -> str:
    days = _absent_days(student, marks)
    dates = ", ".join(day.isoformat() for day in days)
    return (
        f"Dear parent, {student.first_name} "
        f"{student.last_name} missed {len(days)} day(s): "
        f"{dates}."
    )
